import{_ as t,o as r,c as a,ag as i}from"./chunks/framework.DqVSm8kp.js";const s="/llmxray/docs/educators/fr/temperature-distribution.svg",o="/llmxray/docs/educators/fr/temperature-cliff.svg",n="/llmxray/docs/educators/fr/sampling-methods.svg",b=JSON.parse('{"title":"Module 2 : Comment fonctionne la Température ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-2.md","filePath":"fr/community/educators/module-2.md"}'),l={name:"fr/community/educators/module-2.md"};function u(d,e,p,c,m,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="module-2-comment-fonctionne-la-temperature" tabindex="-1">Module 2 : Comment fonctionne la Température ? <a class="header-anchor" href="#module-2-comment-fonctionne-la-temperature" aria-label="Permalink to &quot;Module 2 : Comment fonctionne la Température ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>L&#39;Expérimentateur</strong> — Trouvez la transition de phase</p><p><strong>Durée :</strong> 60 min | <strong>Difficulté :</strong> Débutant | <strong>Prérequis :</strong> <a href="./module-1.html">Module 1</a></p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>La température n&#39;est pas un curseur de créativité — c&#39;est une redistribution de probabilités. Et elle ne se dégrade pas progressivement. Il y a un précipice.</p></blockquote><p>Les étudiants découvrent que la température contrôle une transformation mathématique de la distribution de probabilités sur le vocabulaire. De petits changements près du précipice produisent des variations de qualité spectaculaires — une transition de phase, pas une échelle linéaire.</p><p><img src="'+s+'" alt="How Temperature Reshapes the Probability Distribution"></p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="ce-que-la-temperature-fait-reellement" tabindex="-1">Ce que la température fait réellement <a class="header-anchor" href="#ce-que-la-temperature-fait-reellement" aria-label="Permalink to &quot;Ce que la température fait réellement&quot;">​</a></h3><p>Après que le modèle a calculé un score (logit) pour chaque token du vocabulaire, ces scores passent par une <strong>fonction softmax</strong> pour produire des probabilités. La température modifie ce softmax :</p><p><strong>Softmax standard :</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(token_i) = exp(z_i) / sum_j exp(z_j)</span></span></code></pre></div><p><strong>Softmax avec température T :</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(token_i) = exp(z_i / T) / sum_j exp(z_j / T)</span></span></code></pre></div><p>L&#39;effet :</p><ul><li><strong>T &lt; 1</strong> — Divise les logits par un nombre inférieur à 1, rendant les logits élevés encore plus grands par rapport aux petits. La distribution devient <strong>plus pointue</strong> (plus concentrée). Le token dominant l&#39;emporte.</li><li><strong>T = 1</strong> — Aucune modification. La distribution est telle que le modèle l&#39;a calculée.</li><li><strong>T &gt; 1</strong> — Divise les logits par un nombre supérieur à 1, comprimant tous les logits vers zéro. La distribution devient <strong>plus plate</strong> (plus uniforme). Tous les tokens deviennent à peu près équiprobables.</li><li><strong>T → 0</strong> — La distribution s&#39;effondre en un seul point. Seul le token avec le logit le plus élevé a une probabilité non nulle. C&#39;est le <strong>greedy decoding</strong>.</li></ul><h3 id="pourquoi-c-est-important" tabindex="-1">Pourquoi c&#39;est important <a class="header-anchor" href="#pourquoi-c-est-important" aria-label="Permalink to &quot;Pourquoi c&#39;est important&quot;">​</a></h3><p>La température est le paramètre le plus couramment ajusté lors de l&#39;utilisation des LLM, mais elle est largement mal comprise. On la décrit souvent comme &quot;créativité vs précision&quot; — mais c&#39;est une simplification. Ce qu&#39;elle contrôle réellement, c&#39;est l&#39;<strong>entropie de la distribution d&#39;échantillonnage</strong>.</p><p>Entropie basse = sortie prévisible et répétitive. Entropie élevée = sortie diverse et surprenante, mais potentiellement incohérente. Le bon réglage dépend entièrement de la tâche.</p><h3 id="la-transition-de-phase" tabindex="-1">La transition de phase <a class="header-anchor" href="#la-transition-de-phase" aria-label="Permalink to &quot;La transition de phase&quot;">​</a></h3><p>Contrairement à un bouton de volume qui passe progressivement de silencieux à fort, la température présente une <strong>transition de phase</strong>. La qualité de sortie reste élevée sur une large plage (T=0 à T≈0.8-1.0), puis chute brutalement dans une bande étroite. Cela s&#39;explique par :</p><ol><li>À basses températures, le token dominant a une probabilité si élevée que l&#39;échantillonnage est quasi déterministe dans tous les cas</li><li>À températures modérées, les 3 à 5 premiers tokens se partagent l&#39;essentiel de la probabilité — des choix encore raisonnables</li><li>À un point critique, suffisamment de probabilité fuit vers des tokens improbables pour que le modèle commence à générer du texte incohérent</li><li>Au-delà du précipice, la sortie devient essentiellement aléatoire</li></ol><p><img src="'+o+'" alt="The Temperature Cliff"></p><h3 id="autres-methodes-de-sampling" tabindex="-1">Autres méthodes de sampling <a class="header-anchor" href="#autres-methodes-de-sampling" aria-label="Permalink to &quot;Autres méthodes de sampling&quot;">​</a></h3><p>La température n&#39;est pas la seule façon de contrôler la sélection de tokens. Les LLM modernes prennent en charge plusieurs stratégies de sampling qui peuvent être combinées :</p><p><img src="'+n+'" alt="Sampling Methods Compared"></p><table tabindex="0"><thead><tr><th>Méthode</th><th>Ce qu&#39;elle fait</th><th>Quand l&#39;utiliser</th></tr></thead><tbody><tr><td><strong>Greedy (T=0)</strong></td><td>Choisit toujours le token de plus haute probabilité</td><td>Réponses factuelles, sortie déterministe</td></tr><tr><td><strong>Temperature</strong></td><td>Remodèle la distribution de probabilités</td><td>Contrôle polyvalent de la variété des sorties</td></tr><tr><td><strong>Top-k</strong></td><td>Échantillonne uniquement parmi les k tokens de plus haute probabilité</td><td>Contrôle de diversité simple, ensemble de candidats fixe</td></tr><tr><td><strong>Top-p (nucleus)</strong></td><td>Échantillonne parmi le plus petit ensemble de tokens dont la probabilité cumulée dépasse p</td><td>Diversité adaptative — plus d&#39;options en cas d&#39;incertitude, moins en cas de confiance</td></tr><tr><td><strong>Min-p</strong></td><td>Supprime les tokens dont la probabilité est inférieure à une fraction du token dominant</td><td>Alternative plus récente à top-p, seuil plus intuitif</td></tr><tr><td><strong>Mirostat</strong></td><td>Ajuste dynamiquement le sampling pour maintenir une perplexité cible</td><td>Niveau de &quot;surprise&quot; constant quel que soit le contexte</td></tr><tr><td><strong>Pénalité de répétition</strong></td><td>Réduit la probabilité des tokens récemment générés</td><td>Empêche les boucles et le texte répétitif</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Ces méthodes se composent</p><p>En pratique, plusieurs méthodes sont appliquées en séquence : la température d&#39;abord (remodèle la distribution), puis top-k ou top-p (tronque la distribution), puis l&#39;échantillonnage parmi ce qui reste. La fonctionnalité Compare de LLMxRay vous permet de tester différentes combinaisons côte à côte.</p></div><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-le-balayage-de-temperature" tabindex="-1">Exercice 1 : Le balayage de température <a class="header-anchor" href="#exercice-1-le-balayage-de-temperature" aria-label="Permalink to &quot;Exercice 1 : Le balayage de température&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ouvrez <strong>Compare</strong> dans LLMxRay</li><li>Cliquez sur le preset <strong>Temperature Sweep</strong> — cela crée 3 emplacements avec des températures de 0.2, 0.7 et 1.2</li><li>Ajoutez un 4e emplacement manuellement et réglez-le à 2.0</li><li>Utilisez ce prompt : <em>&quot;Write a function in Python to check if a number is prime&quot;</em></li><li>Cliquez sur <strong>Run All</strong> et observez les 4 générer simultanément</li><li>Comparez les résultats en <strong>Grid View</strong></li></ol><p><strong>Ce qu&#39;il faut observer :</strong></p><ul><li><strong>T=0.2</strong> : Implémentation propre et standard. Quasi identique si vous la relancez.</li><li><strong>T=0.7</strong> : Légères variations dans les noms de variables ou les commentaires. Toujours correct.</li><li><strong>T=1.2</strong> : Approches plus créatives (peut-être un algorithme différent), mais attention aux bugs subtils.</li><li><strong>T=2.0</strong> : Les noms de variables deviennent étranges, des erreurs de logique apparaissent, potentiellement incomplet.</li></ul><p>Passez en <strong>Diff View</strong> pour voir exactement quels mots ont changé entre les sorties.</p><p><strong>Question clé :</strong> Entre quelles deux températures la chute de qualité vous semble-t-elle la plus marquée ?</p><hr><h3 id="exercice-2-trouver-le-precipice" tabindex="-1">Exercice 2 : Trouver le précipice <a class="header-anchor" href="#exercice-2-trouver-le-precipice" aria-label="Permalink to &quot;Exercice 2 : Trouver le précipice&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Restez dans <strong>Compare</strong>. Configurez 4 emplacements avec les températures : 0.7, 0.9, 1.1, 1.3</li><li>Prompt : <em>&quot;Write a function in Python to check if a number is prime&quot;</em></li><li>Exécutez 3 fois. Pour chaque exécution, notez si chaque emplacement a produit du code correct (Oui/Non)</li><li>Consignez vos résultats dans un tableau :</li></ol><table tabindex="0"><thead><tr><th>Température</th><th>Exec 1</th><th>Exec 2</th><th>Exec 3</th><th>Taux de réussite</th></tr></thead><tbody><tr><td>0.7</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>0.9</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>1.1</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>1.3</td><td></td><td></td><td></td><td>/3</td></tr></tbody></table><ol start="5"><li>Le précipice se situe là où le taux de réussite chute brutalement — généralement entre T=0.9 et T=1.2</li></ol><p><strong>Pourquoi c&#39;est important :</strong></p><p>Cela démontre que la température n&#39;est pas un compromis linéaire. Il y a une <strong>bande étroite</strong> où la sortie passe de &quot;presque toujours correcte&quot; à &quot;généralement fausse&quot;. Trouver ce précipice pour votre modèle et votre tâche spécifiques est l&#39;une des compétences les plus pratiques en prompt engineering.</p><hr><h3 id="exercice-3-temperature-vs-type-de-tache" tabindex="-1">Exercice 3 : Température vs type de tâche <a class="header-anchor" href="#exercice-3-temperature-vs-type-de-tache" aria-label="Permalink to &quot;Exercice 3 : Température vs type de tâche&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Configurez 2 emplacements : tous deux avec le même modèle, l&#39;un à T=0.2, l&#39;autre à T=1.0</li><li><strong>Prompt factuel :</strong> <em>&quot;What is the capital of France?&quot;</em><ul><li>Exécutez-le. Les deux devraient répondre &quot;Paris.&quot; La basse température n&#39;apporte rien ici.</li></ul></li><li><strong>Prompt créatif :</strong> <em>&quot;Write a haiku about debugging code at midnight&quot;</em><ul><li>Exécutez-le 3 fois. Comparez la variété.</li><li>À T=0.2, vous obtiendrez quasiment le même haiku à chaque fois.</li><li>À T=1.0, vous obtiendrez des expressions créatives véritablement différentes.</li></ul></li><li><strong>Prompt de raisonnement :</strong> <em>&quot;A farmer has 15 sheep. All but 8 run away. How many sheep does the farmer have left?&quot;</em><ul><li>C&#39;est une question piège (réponse : 8, pas 7). Testez aux deux températures.</li><li>La température affecte-t-elle la précision du raisonnement ?</li></ul></li></ol><p><strong>Discussion :</strong> Pourquoi n&#39;y a-t-il pas de température &quot;idéale&quot; unique ? Quelle température choisiriez-vous pour :</p><ul><li>Un chatbot de support client ?</li><li>Un assistant d&#39;écriture créative ?</li><li>Un outil de complétion de code ?</li><li>Un système d&#39;information médicale ?</li></ul><hr><h3 id="exercice-4-determinisme-et-seeds" tabindex="-1">Exercice 4 : Déterminisme et seeds <a class="header-anchor" href="#exercice-4-determinisme-et-seeds" aria-label="Permalink to &quot;Exercice 4 : Déterminisme et seeds&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Dans <strong>Compare</strong>, utilisez le preset <strong>Deterministic Pair</strong> — deux emplacements avec le même modèle, les mêmes paramètres, le même seed, T=0</li><li>Exécutez le même prompt 3 fois</li><li>Toutes les sorties devraient être <strong>identiques</strong> — le seed rend le générateur de nombres aléatoires reproductible</li><li>Maintenant changez un emplacement à T=0.7 (gardez le même seed)</li><li>Exécutez à nouveau 3 fois — les sorties différeront désormais entre les exécutions</li></ol><p><strong>Ce que cela révèle :</strong></p><ul><li>À T=0 (greedy), le seed n&#39;a pas d&#39;importance — il n&#39;y a pas d&#39;aléatoire à contrôler</li><li>À T&gt;0, le seed contrôle quel chemin aléatoire est emprunté dans la distribution</li><li>Même seed + même température = aléatoire reproductible</li><li>C&#39;est ainsi que les chercheurs assurent la reproductibilité des expériences tout en utilisant le décodage stochastique</li></ul><div class="tip custom-block"><p class="custom-block-title">Pourquoi la reproductibilité est importante</p><p>En recherche et en production, vous devez pouvoir reproduire des sorties spécifiques pour le débogage, la comparaison et l&#39;audit. Fixer un seed avec une température modérée vous donne une <strong>variété contrôlée</strong> — différente du greedy (toujours identique) mais reproductible quand nécessaire.</p></div><hr><h2 id="points-cles" tabindex="-1">Points Clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Clés&quot;">​</a></h2><ol><li><strong>La température est une opération mathématique</strong> — elle divise les logits par T avant le softmax, remodelant la distribution de probabilités</li><li><strong>Le précipice est réel</strong> — la qualité ne se dégrade pas linéairement ; il y a une transition brusque où la sortie passe de fiable à chaotique</li><li><strong>Il n&#39;y a pas de température universellement optimale</strong> — la valeur idéale dépend de la tâche (factuelle, créative, raisonnement)</li><li><strong>La température se compose avec d&#39;autres méthodes</strong> — top-k, top-p et la pénalité de répétition fonctionnent conjointement avec la température</li><li><strong>Les seeds permettent la reproductibilité</strong> — seed fixe + température fixe = même sortie à chaque fois</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><ol><li>Si une entreprise déploie un chatbot à T=0 pour la sécurité, que perd-elle ? Une sortie déterministe est-elle toujours &quot;plus sûre&quot; ?</li><li>La position du précipice varie selon le modèle. Pourquoi un modèle de 70B paramètres pourrait-il avoir une température de précipice plus élevée qu&#39;un modèle de 3B ?</li><li>Les assistants d&#39;écriture créative utilisent souvent T=0.8-1.0. Mais à qui appartient la créativité — à l&#39;utilisateur ou au modèle ? La température change-t-elle cela ?</li><li>Si vous ne pouviez ajuster qu&#39;un seul paramètre (température, top-k ou top-p), lequel choisiriez-vous et pourquoi ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complémentaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles académiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles académiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Année</th><th>Lien</th></tr></thead><tbody><tr><td>The Curious Case of Neural Text Degeneration</td><td>Holtzman, Buys, Du, Forbes, Choi</td><td>2019</td><td><a href="https://arxiv.org/abs/1904.09751" target="_blank" rel="noreferrer">arXiv:1904.09751</a></td></tr><tr><td>Hierarchical Neural Story Generation</td><td>Fan, Lewis, Dauphin</td><td>2018</td><td><a href="https://arxiv.org/abs/1805.04833" target="_blank" rel="noreferrer">arXiv:1805.04833</a></td></tr><tr><td>Mirostat: A Neural Text Decoding Algorithm</td><td>Basu, Anay, Tan, Yarin</td><td>2020</td><td><a href="https://arxiv.org/abs/2007.14966" target="_blank" rel="noreferrer">arXiv:2007.14966</a></td></tr><tr><td>Attention Is All You Need</td><td>Vaswani et al.</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr></tbody></table><h3 id="tutoriels-et-explications" tabindex="-1">Tutoriels et explications <a class="header-anchor" href="#tutoriels-et-explications" aria-label="Permalink to &quot;Tutoriels et explications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Auteur</th><th>Lien</th></tr></thead><tbody><tr><td>Sampling Parameters Explained: Intuition to Math</td><td>Let&#39;s Data Science</td><td><a href="https://letsdatascience.com/blog/llm-sampling-temperature-top-k-top-p-and-min-p-explained" target="_blank" rel="noreferrer">letsdatascience.com</a></td></tr><tr><td>Generation Configurations: Temperature, Top-k, Top-p</td><td>Chip Huyen</td><td><a href="https://huyenchip.com/2024/01/16/sampling.html" target="_blank" rel="noreferrer">huyenchip.com</a></td></tr><tr><td>Token Sampling Methods Primer</td><td>Aman.ai</td><td><a href="https://aman.ai/primers/ai/token-sampling/" target="_blank" rel="noreferrer">aman.ai/primers/ai/token-sampling</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr></tbody></table><h3 id="concepts-cles" tabindex="-1">Concepts clés <a class="header-anchor" href="#concepts-cles" aria-label="Permalink to &quot;Concepts clés&quot;">​</a></h3><p><strong>Le nucleus sampling (top-p)</strong> a été introduit par Holtzman et al. (2019) en réponse à l&#39;observation que le sampling standard avec température produit un texte soit trop générique (basse T) soit trop aléatoire (haute T). Leur idée : plutôt qu&#39;une température fixe, tronquer la distribution au plus petit ensemble de tokens couvrant un seuil de probabilité cumulée. Cela s&#39;adapte automatiquement — quand le modèle est confiant, moins de tokens sont considérés ; quand il est incertain, davantage d&#39;options restent disponibles.</p><p><strong>Mirostat</strong> (Basu et al., 2020) va plus loin en ciblant un niveau de perplexité spécifique plutôt qu&#39;une forme de distribution fixe. Il ajuste dynamiquement le sampling pour maintenir un niveau de &quot;surprise&quot; constant, que le modèle génère une expression prévisible ou navigue en territoire incertain.</p><hr><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p><strong>Option A — Collecte de données (individuel, 1 page) :</strong> Effectuez l&#39;expérience de recherche du précipice (Exercice 2) avec 5 valeurs de température et 5 exécutions chacune. Présentez un tableau et un graphique linéaire du taux de réussite en fonction de la température. Identifiez le point de précipice pour votre modèle.</p><p><strong>Option B — Analyse comparative (en binôme, 1 page) :</strong> Testez le même prompt pour 3 types de tâches (factuelle, créative, raisonnement) à 4 températures. Pour chaque combinaison, évaluez la qualité de sortie sur une échelle de 1 à 5. Présentez une heatmap et recommandez les températures optimales par type de tâche.</p><p><strong>Option C — Explication technique (individuel, 500 mots) :</strong> Expliquez à un chef de produit non technique pourquoi son chatbot ne devrait PAS utiliser T=0, malgré le fait que ce soit &quot;l&#39;option la plus sûre&quot;. Utilisez des exemples concrets tirés de vos expériences.</p><hr><h2 id="la-suite" tabindex="-1">La suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-3.html">Module 3 : L&#39;IA peut-elle mentir ?</a></strong>, vous utiliserez ce que vous avez appris sur les distributions de probabilités pour comprendre la <strong>confiance vs la vérité</strong>. Un modèle peut attribuer 95 % de probabilité à la mauvaise réponse — et vous découvrirez pourquoi grâce aux benchmarks avec de vrais logprobs.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 2 sur 8</strong> du Kit Enseignants LLMxRay <a href="./module-1.html">← Module 1 : Qu&#39;est-ce qu&#39;un token ?</a> | <a href="./index.html">Retour au programme</a> | <a href="./module-3.html">Module 3 : L&#39;IA peut-elle mentir ? →</a></p></div>',83)])])}const q=t(l,[["render",u]]);export{b as __pageData,q as default};
